/**
 * Converts the third-party anatomical heart FBX in `3d heart/source` into a
 * single self-contained GLB for the web app.
 *
 * The FBX's PBR maps are embedded as PNG images inside the GLB rather than kept
 * as loose files, so the browser makes one request and GLTFLoader assigns the
 * correct colour spaces (sRGB for base colour, linear for normal/roughness).
 *
 * Usage: node scripts/heart/build-heart-glb.mjs
 * Source: 3d heart/ (user-supplied asset, not generated by this project)
 */
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { deflateSync, inflateSync } from 'node:zlib';
import * as THREE from 'three';
import { FBXLoader } from 'three/examples/jsm/loaders/FBXLoader.js';
import { GLTFExporter } from 'three/examples/jsm/exporters/GLTFExporter.js';

const PNG_SIGNATURE = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);

function crc32(buffer) {
  let crc = 0xffffffff;
  for (const byte of buffer) {
    let c = (crc ^ byte) & 0xff;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    crc = (crc >>> 8) ^ c;
  }
  return (crc ^ 0xffffffff) >>> 0;
}

function pngChunk(type, data) {
  const length = Buffer.alloc(4);
  length.writeUInt32BE(data.length);
  const typed = Buffer.concat([Buffer.from(type, 'latin1'), data]);
  const crc = Buffer.alloc(4);
  crc.writeUInt32BE(crc32(typed));
  return Buffer.concat([length, typed, crc]);
}

/**
 * Rewrites a 16-bit RGB/RGBA PNG as 8-bit RGB, optionally halving its size.
 * The supplied normal map is 16-bit and ~13 MB, which is far more precision than
 * a tangent-space normal on a 300 px-wide render can use.
 */
function optimisePng(input, { halve = false } = {}) {
  const view = new DataView(input.buffer, input.byteOffset, input.byteLength);
  let offset = 8;
  let width = 0;
  let height = 0;
  let bitDepth = 0;
  let colorType = 0;
  const data = [];

  while (offset < input.length) {
    const length = view.getUint32(offset);
    const type = input.toString('latin1', offset + 4, offset + 8);
    const body = input.subarray(offset + 8, offset + 8 + length);
    if (type === 'IHDR') {
      width = body.readUInt32BE(0);
      height = body.readUInt32BE(4);
      bitDepth = body[8];
      colorType = body[9];
      if (body[12] !== 0) throw new Error('interlaced PNG is not supported');
      if (bitDepth !== 16 || (colorType !== 2 && colorType !== 6)) {
        throw new Error(`unexpected PNG format (bitDepth ${bitDepth}, colorType ${colorType})`);
      }
    } else if (type === 'IDAT') {
      data.push(body);
    } else if (type === 'IEND') {
      break;
    }
    offset += length + 12;
  }

  const channels = colorType === 6 ? 4 : 3;
  const bpp = channels * 2;
  const stride = width * bpp;
  const raw = inflateSync(Buffer.concat(data));
  const pixels = Buffer.alloc(stride * height);

  for (let y = 0; y < height; y++) {
    const filter = raw[y * (stride + 1)];
    const line = raw.subarray(y * (stride + 1) + 1, (y + 1) * (stride + 1));
    const out = pixels.subarray(y * stride, (y + 1) * stride);
    const prior = y > 0 ? pixels.subarray((y - 1) * stride, y * stride) : null;
    for (let x = 0; x < stride; x++) {
      const a = x >= bpp ? out[x - bpp] : 0;
      const b = prior ? prior[x] : 0;
      const c = prior && x >= bpp ? prior[x - bpp] : 0;
      let value = line[x];
      if (filter === 1) value += a;
      else if (filter === 2) value += b;
      else if (filter === 3) value += (a + b) >> 1;
      else if (filter === 4) {
        const p = a + b - c;
        const pa = Math.abs(p - a);
        const pb = Math.abs(p - b);
        const pc = Math.abs(p - c);
        value += pa <= pb && pa <= pc ? a : pb <= pc ? b : c;
      }
      out[x] = value & 0xff;
    }
  }

  const scale = halve ? 2 : 1;
  const outWidth = width / scale;
  const outHeight = height / scale;
  const rgb = Buffer.alloc(outWidth * outHeight * 3);

  for (let y = 0; y < outHeight; y++) {
    for (let x = 0; x < outWidth; x++) {
      let r = 0;
      let g = 0;
      let b = 0;
      for (let sy = 0; sy < scale; sy++) {
        for (let sx = 0; sx < scale; sx++) {
          const i = ((y * scale + sy) * width + (x * scale + sx)) * bpp;
          r += pixels[i];
          g += pixels[i + 2];
          b += pixels[i + 4];
        }
      }
      const count = scale * scale;
      const o = (y * outWidth + x) * 3;
      rgb[o] = Math.round(r / count);
      rgb[o + 1] = Math.round(g / count);
      rgb[o + 2] = Math.round(b / count);
    }
  }

  const scanlines = Buffer.alloc((outWidth * 3 + 1) * outHeight);
  for (let y = 0; y < outHeight; y++) {
    scanlines[y * (outWidth * 3 + 1)] = 0;
    rgb.copy(scanlines, y * (outWidth * 3 + 1) + 1, y * outWidth * 3, (y + 1) * outWidth * 3);
  }

  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(outWidth, 0);
  ihdr.writeUInt32BE(outHeight, 4);
  ihdr[8] = 8;
  ihdr[9] = 2;

  return Buffer.concat([
    PNG_SIGNATURE,
    pngChunk('IHDR', ihdr),
    pngChunk('IDAT', deflateSync(scanlines, { level: 9 })),
    pngChunk('IEND', Buffer.alloc(0)),
  ]);
}

const root = resolve(dirname(fileURLToPath(import.meta.url)), '../..');
const SRC = resolve(root, '3d heart');
const OUT = resolve(root, 'public/models/heart');
const TEX = (name) => resolve(SRC, 'textures', `hart_UV_low01_${name}.hart_UV_low_defaultMat.png`);

// The FBX references the external maps by relative path; they are embedded below
// instead, so stub texture loading out while parsing the mesh.
THREE.TextureLoader.prototype.load = function load() {
  return new THREE.Texture();
};

// GLTFExporter reads its merged buffer back with FileReader, which Node lacks.
if (typeof globalThis.FileReader === 'undefined') {
  globalThis.FileReader = class FileReader {
    constructor() {
      this.result = null;
      this.onloadend = null;
    }

    readAsArrayBuffer(blob) {
      blob.arrayBuffer().then((buffer) => {
        this.result = buffer;
        if (this.onloadend) this.onloadend({ target: this });
      });
    }
  };
}

const buffer = readFileSync(resolve(SRC, 'source/Heart.fbx')).buffer;
const object = new FBXLoader().parse(buffer, '');

let meshes = 0;
let triangles = 0;
const box = new THREE.Box3();
object.traverse((child) => {
  if (!child.isMesh) return;
  meshes += 1;
  const geo = child.geometry;
  triangles += (geo.index ? geo.index.count : geo.attributes.position.count) / 3;
  geo.computeBoundingBox();
  box.union(geo.boundingBox);
  child.material = new THREE.MeshStandardMaterial({ name: `heart-${meshes}` });

  // FBX stores UVs with V up; glTF loads textures with flipY = false (V down),
  // and GLTFExporter passes UVs through untouched. Without this flip every
  // island samples the atlas vertically mirrored — which showed up as flat pale
  // patches of "fat" painted across the ventricle instead of over the atria.
  const uv = geo.attributes.uv;
  if (uv) {
    for (let i = 1; i < uv.array.length; i += 2) uv.array[i] = 1 - uv.array[i];
    uv.needsUpdate = true;
  }
});

const size = box.getSize(new THREE.Vector3());
console.log(`meshes: ${meshes}`);
console.log(`triangles: ${Math.round(triangles).toLocaleString()}`);
console.log(`bounds: ${box.min.toArray().map((n) => n.toFixed(3)).join(', ')} → ${box.max.toArray().map((n) => n.toFixed(3)).join(', ')}`);
console.log(`size: ${size.toArray().map((n) => n.toFixed(3)).join(', ')}`);

const exported = await new GLTFExporter().parseAsync(object, { binary: true, onlyVisible: false });

/**
 * Appends the maps to an existing GLB and points the material at them.
 * Roughness is packed in the green channel of the metallic-roughness texture and
 * `metallicFactor` is 0, so a plain greyscale roughness map is safe to use.
 */
function embedMaps(glb, maps) {
  const view = new DataView(glb);
  const jsonLength = view.getUint32(12, true);
  const json = JSON.parse(new TextDecoder().decode(new Uint8Array(glb, 20, jsonLength)));
  const binHeader = 20 + jsonLength;
  const binLength = view.getUint32(binHeader, true);
  const bin = new Uint8Array(glb, binHeader + 8, binLength);

  const chunks = [bin];
  let offset = binLength;
  json.bufferViews = json.bufferViews ?? [];
  json.images = [];

  maps.forEach((map, index) => {
    const padding = (4 - (offset % 4)) % 4;
    if (padding > 0) {
      chunks.push(new Uint8Array(padding));
      offset += padding;
    }

    const bytes = map.optimise ? optimisePng(readFileSync(map.file), map.optimise) : readFileSync(map.file);
    json.bufferViews.push({ buffer: 0, byteOffset: offset, byteLength: bytes.length });
    json.images.push({ bufferView: json.bufferViews.length - 1, mimeType: 'image/png', name: map.name });
    chunks.push(new Uint8Array(bytes));
    offset += bytes.length;
    json.textures = [...(json.textures ?? []), { sampler: 0, source: index }];
  });

  const merged = new Uint8Array(offset);
  let cursor = 0;
  for (const chunk of chunks) {
    merged.set(chunk, cursor);
    cursor += chunk.length;
  }

  json.samplers = [{ magFilter: 9729, minFilter: 9987, wrapS: 33071, wrapT: 33071 }];
  json.buffers = [{ byteLength: merged.length }];

  const material = json.materials[0];
  material.pbrMetallicRoughness.baseColorTexture = { index: 0 };
  material.pbrMetallicRoughness.metallicRoughnessTexture = { index: 1 };
  material.pbrMetallicRoughness.metallicFactor = 0;
  material.pbrMetallicRoughness.roughnessFactor = 1;
  material.normalTexture = { index: 2 };

  const jsonBytes = new TextEncoder().encode(JSON.stringify(json));
  const jsonPadded = new Uint8Array(Math.ceil(jsonBytes.length / 4) * 4).fill(0x20);
  jsonPadded.set(jsonBytes);
  const binPadded = new Uint8Array(Math.ceil(merged.length / 4) * 4);
  binPadded.set(merged);

  const total = 12 + 8 + jsonPadded.length + 8 + binPadded.length;
  const out = new ArrayBuffer(total);
  const outView = new DataView(out);
  const outBytes = new Uint8Array(out);

  outView.setUint32(0, 0x46546c67, true); // 'glTF'
  outView.setUint32(4, 2, true);
  outView.setUint32(8, total, true);
  outView.setUint32(12, jsonPadded.length, true);
  outView.setUint32(16, 0x4e4f534a, true); // 'JSON'
  outBytes.set(jsonPadded, 20);
  outView.setUint32(20 + jsonPadded.length, binPadded.length, true);
  outView.setUint32(24 + jsonPadded.length, 0x004e4942, true); // 'BIN\0'
  outBytes.set(binPadded, 28 + jsonPadded.length);

  return out;
}

const glb = embedMaps(exported, [
  { name: 'BaseColor', file: TEX('BaseColor') },
  { name: 'Roughness', file: TEX('Roughness') },
  { name: 'Normal', file: TEX('Normal'), optimise: { halve: true } },
]);

mkdirSync(OUT, { recursive: true });
writeFileSync(resolve(OUT, 'heart.glb'), Buffer.from(glb));
console.log(`wrote public/models/heart/heart.glb (${(glb.byteLength / 1024 / 1024).toFixed(2)} MiB, textures embedded)`);
